};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.btn_search_onclick = function(e) {
    scwin.listSync();
};

scwin.btn_excel_onclick = function(e) {
    // if (dlt_selectListRes.CountRow > 0) {
    //     //엑셀 로그 
    //     $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);

	// //----W-Craft WebSquare 변환 확인: GridToOffice----//
    //     grd_grid.GridToOffice("평가기관담당자", "", 8, 0);
    // } else {
    //     alert(NO_EXCEL_DATA);
    // }

    if (grd_grid.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    grd_grid.advancedExcelDownload({fileName: "", sheetName: "평가기관담당자"});
};

scwin.dlt_selectListRes_OnLoadCompleted = function(rowcount) {
    $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
};

scwin.dlt_selectListRes_OnLoadError = function() {
    $c.win.alert(dlt_selectListRes);
};

/* 행추가 버튼 */
scwin.btn_new_onclick = function(e) {
    dlt_selectListRes.insertRow();
    scwin.tbx_totCnt_change();
    scwin.refreshNo();
};

scwin.ibx_chrgNm_onkeydown = function(e) {
    if (e.keyCode === 13) {
        scwin.listSync();
    }
};

/* 행삭제 버튼 */
scwin.btn_delete_onclick = function(e) {
    const checkedRows = grd_grid.getCheckedIndex("chkYn");
    for (let i=checkedRows.length-1; i>=0; i--) {
        grd_grid.setRowVisible(checkedRows[i], false);
        dlt_selectListRes.deleteRow(checkedRows[i]);
        // removeRow로 완전 삭제하면 저장할 때 삭제할 row가 없어서 안보이게 감춰둔다.
    }
    scwin.tbx_totCnt_change();
    scwin.refreshNo();
};

/* 저장버튼 */
scwin.btn_modify_onclick = function(e) {
    scwin.save();
};

scwin.trs_Save_OnFail = function() {
    $c.lce.fn_alertMsg('F');
};

scwin.trs_Save_OnSuccess = function() {
    $c.lce.fn_alertMsg('S');
    scwin.listSync();
};

scwin.grd_grid_OnDblClick = function(row, colid) {
    if (scwin.isSetPopup && !scwin.isMailPopup) {
        let arrPar = new Array();

        //----W-Craft WebSquare 변환 확인: fn_SetPar----//
        if (scwin.fn_SetPar !== undefined) {

            // TODO Stage2: 0-based 검토
            arrPar[0] = dlt_selectListRes.getCellData(dlt_selectListRes.getRowPosition(), 'chrgNm');

            // TODO Stage2: 0-based 검토
            arrPar[1] = dlt_selectListRes.getCellData(dlt_selectListRes.getRowPosition(), 'comTelNo');

            // TODO Stage2: 0-based 검토
            arrPar[2] = dlt_selectListRes.getCellData(dlt_selectListRes.getRowPosition(), 'chrgEmail');

            //----W-Craft WebSquare 변환 확인: fn_SetPar----//
            scwin.fn_SetPar(arrPar);
        }

        $c.win.closePopup();
    }
};

scwin.btn_select_onclick = function(e) {
    scwin.chkSelect();
};

// 일반 함수
/**
 * 콤보박스 값 설정
 */
scwin.searchCode = function() {
    let reqMap = {
        codeList: "SPECY_VALU_INST_CD", //코드정보 List
    };
    $c.sbm.execute(sbm_listCodeValue1, reqMap);
};

scwin.grdSearchCode = function() {
    let reqMap = {
        codeList: "SPECY_VALU_INST_CD, SPECY_VALU_INST_TP_CD", //코드정보 List
    };
    $c.sbm.execute(sbm_listCodeValue2, reqMap);
};

scwin.listSync = function() {

    let reqMap = {
        specyValuInstCd: sbx_specyValuInstCd.getValue(), //기관코드
        chrgNm: ibx_chrgNm.getValue(), //담당자명
    };
    $c.sbm.execute(sbm_selectList, reqMap);
};

/* 저장 가능여부 확인 */
scwin.save = function() {
    TR_JOB = 'I';
    if (scwin.checkForm()) {
        // list_common.fn_isProcess -> $c.lc.fn_isProcess
        // if (!scwin.fn_isProcess(TR_JOB)) return;
        scwin.trs();
    }
};

scwin.checkForm = function() {
    for (let i = 0; i < dlt_selectListRes.getRowCount(); i++) {

        const status = dlt_selectListRes.getRowStatus(i);
        // C:신규, U:수정, D:삭제, R:읽기/변경없음
        if (status === "C" || status === "U") {

            if (dlt_selectListRes.getCellData(i, "specyValuInstCd") === "") {
                alert((i+1) + "번째행" + " 기관명은 필수값입니다.");
                return false;
            }

            if (dlt_selectListRes.getCellData(i, "specyValuInstTpCd") === "") {
                alert((i+1) + "번째행" + " 구분값은 필수값입니다.");
                return false;
            }
        }
    }
    return true;
};

/* 저장 기능 submission */
scwin.trs = function() {
    // if (TR_JOB == "I") {
    //     vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    // }

    for (let i = 0; i < dlt_selectListRes.getRowCount(); i++) {

        // [rowStatus] C:신규, U:수정, D:삭제, R:읽기/변경없음 --->>> I, U 로 바꿔서 보내주기
        if (dlt_selectListRes.getRowStatus(i) === "R") {
            dlt_selectListRes.modifyRowStatus(i, "U");
        } else if (dlt_selectListRes.getRowStatus(i) === "C") {
            dlt_selectListRes.modifyRowStatus(i, "I");
        }
    }

    $c.sbm.execute(sbm_save, dlt_selectListRes.getAllJSON());
};

scwin.chkSelect = function() {
    let arrPar;
    let selNum = 0;
    let isFirst = true;
    for (let i = 1, j = dlt_selectListRes.getRowCount(); i <= j; i++) {

        if (dlt_selectListRes.getCellData(i, "chkYn") === "T") {
            arrPar = new Array();

            arrPar[0] = dlt_selectListRes.getCellData(i, 'chrgNm');

            arrPar[1] = dlt_selectListRes.getCellData(i, 'chrgEmail');
            selNum++;

            //----W-Craft WebSquare 변환 확인: fn_SetPar----//
            if (scwin.fn_SetPar !== undefined) {
                if (selNum !== 1) {
                    isFirst = false;
                }

                //----W-Craft WebSquare 변환 확인: fn_SetPar----//
                scwin.fn_SetPar(arrPar, isFirst);
            }
        }
    }

    $c.win.closePopup();
};

/* 기관명,구분 selectBox 데이터 후 처리 */
scwin.sbm_listCodeValue1_submitdone = function (e) {
    dlt_codRes_cd_sbx.setJSON(e.responseJSON.body.SPECY_VALU_INST_CD);

    // 첫번째 선택으로 ''를 만들어준다.
    dlt_codRes_cd_sbx.insertRow(0);
    dlt_codRes_cd_sbx.setCellData(0, "value", "");
    dlt_codRes_cd_sbx.setCellData(0, "text", "전체");
    sbx_specyValuInstCd.setNodeSet("data:dlt_codRes_cd_sbx", "text", "value");
};

/* 조회 후 처리 */
scwin.sbm_selectList_submitdone = function (e) {
    dlt_selectListRes.setJSON(e.responseJSON.body);
    scwin.tbx_totCnt_change();

    // 행삭제로 보이지 않던 row visible=false 해제
    for (let i=0; i < dlt_selectListRes.getRowCount(); i++) {
        grd_grid.setRowVisible(i, true);
        dlt_selectListRes.setCellData(i, "no", i+1);
    }
    scwin.refreshNo();
};

// grd_grid 이벤트 핸들러
// scwin.grd_grid_onviewchange = function (info) {
//     if (info.colId === "chk") {
//         grd_grid.setFocusedCell(info.rowIndex, info.colIndex);
//     }
// };

/* 순번 refresh */
scwin.refreshNo = function() {
    for (let i=0; i < dlt_selectListRes.getRowCount(); i++) {
        dlt_selectListRes.setCellData(i, "no", i+1);
    }
}

scwin.sbm_listCodeValue2_submitdone = function (e) {
    dlt_codRes_cd.setJSON(e.responseJSON.body.SPECY_VALU_INST_CD);
    dlt_codRes_tpCd.setJSON(e.responseJSON.body.SPECY_VALU_INST_TP_CD);

    // 첫번째 선택으로 ''를 만들어준다.
    dlt_codRes_cd.insertRow(0);
    dlt_codRes_cd.setCellData(0, "value", "");
    dlt_codRes_cd.setCellData(0, "text", "");

    dlt_codRes_tpCd.insertRow(0);
    dlt_codRes_tpCd.setCellData(0, "value", "");
    dlt_codRes_tpCd.setCellData(0, "text", "");
};

/* 총 건수 계산 */
scwin.tbx_totCnt_change = function() {
    let rowCount = 0;
	for (let i = 0; i < dlt_selectListRes.getRowCount(); i++) {
		if (dlt_selectListRes.getRowStatus(i) !== "D") {
			rowCount++;
		}
	}
	tbx_totCnt.setValue(rowCount);
}
